import { test, expect } from '@playwright/test';

test.describe('Mobile header burger menu', () => {
  test('Language switch from burger menu works without page shift @mobile @prod-safe (#1604a7)', async ({ page }) => {
    // 1. Open / (he) as guest.
    await page.goto('/');
    const W = page.viewportSize()!.width;
    const html = page.locator('html');
    const burger = page.locator('header button[aria-expanded]:visible').first();
    const langSwitcher = page.locator('header button[aria-haspopup="listbox"]:visible');
    const logo = page.locator('header a:visible').first();

    // 2-3. Tap burger > language switcher > language, repeated: en, ru, ar, he.
    const steps = [
      { option: 'English', url: /\/en\/?$/, lang: 'en', dir: 'ltr' },
      { option: 'Русский', url: /\/ru\/?$/, lang: 'ru', dir: 'ltr' },
      { option: 'العربية', url: /\/ar\/?$/, lang: 'ar', dir: 'rtl' },
      { option: 'עברית', url: /\.app(\/he)?\/?(\?.*)?$/, lang: 'he', dir: 'rtl' },
    ];

    for (const step of steps) {
      await burger.click();
      await langSwitcher.click();
      await page.getByRole('option', { name: step.option }).click();

      // Expected: URL prefix, <html lang> and dir match the chosen language.
      await expect(page).toHaveURL(step.url);
      await expect(html).toHaveAttribute('lang', step.lang);
      await expect(html).toHaveAttribute('dir', step.dir);

      // Menu closed: no horizontal page scroll.
      await expect(langSwitcher).toBeHidden();
      await expect
        .poll(() => page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth))
        .toBe(true);

      // Header logo fully inside the screen.
      await expect(logo).toBeVisible();
      const box = await logo.boundingBox();
      expect(box).not.toBeNull();
      expect(box!.x).toBeGreaterThanOrEqual(0);
      expect(box!.x + box!.width).toBeLessThanOrEqual(W);
    }
  });
});
